export const ZH_LEXICON_EXTRA: ReadonlyArray<ChineseLexiconEntry> = RAW_EXTRA.map(
  ([slug, hanzi, pinyin, pos, hsk, meaningVi, exampleZh, examplePinyin, exampleVi, topic, variants, senses]) => ({
    id: `zh:ext_${slug}`,
    hanzi,
    pinyin,
    pos,
    ...(hsk ? { hsk } : {}),
    meaningVi,
    exampleZh,
    examplePinyin,
    exampleVi,
    topic,
    ...(variants ? { variants } : {}),
    ...(senses ? { senses } : {}),
  }),
);

